+/// If a Rust raw string opens at byte `index` of `text` (`r`, `br` or `cr`
+/// not preceded by an identifier character, then hashes, then a quote), the
+/// number of hashes and the byte offset after the opening quote.
+fn raw_string_body(text: &str, index: usize) -> Option<(usize, usize)> {
+    let is_identifier = |c: char| c.is_ascii_alphanumeric() || c == '_';
+    let rest = &text[index..];
+    let prefix = if rest.starts_with("br") || rest.starts_with("cr") {
+        2
+    } else if rest.starts_with('r') {
+        1
+    } else {
+        return None;
+    };
+    if text[..index].ends_with(is_identifier) {
+        return None;
+    }
+    let hashes = rest[prefix..].bytes().take_while(|&b| b == b'#').count();
+    rest[prefix + hashes..]
+        .starts_with('"')
+        .then_some((hashes, index + prefix + hashes + 1))
+}
